diff --git a/expat/lib/xmlparse.c b/expat/lib/xmlparse.c
index 8d5d86e..e674fda 100644
--- a/expat/lib/xmlparse.c
+++ b/expat/lib/xmlparse.c
@@ -6239,7 +6239,10 @@ doProlog(XML_Parser parser, const ENCODING *enc, const char *s, const char *end,
           return XML_ERROR_NO_MEMORY;
         name = el->name;
         dtd->scaffold[myindex].name = name;
-        nameLen = xcslen(name) + /*null terminator*/ 1;
+        /* Count the characters of the name here; the NUL terminator that
+           build_model() writes after each name is reserved there, once, per
+           scaffold node. */
+        nameLen = xcslen(name);

         /* Detect and prevent integer overflow */
         if (nameLen > UINT_MAX - dtd->contentStringLen) {
@@ -8497,6 +8500,15 @@ build_model(XML_Parser parser) {
   XML_Content *ret;
   XML_Char *str; /* the current string writing location */

+  /* dtd->contentStringLen counts the characters of all content-model names;
+   * build_model() writes a NUL terminator after each name, so reserve one
+   * extra XML_Char per scaffold node (an upper bound on the number of names
+   * among the nodes). */
+  if (dtd->contentStringLen > UINT_MAX - dtd->scaffCount) {
+    return NULL;
+  }
+  const unsigned stringCharCount = dtd->contentStringLen + dtd->scaffCount;
+
   /* Detect and prevent integer overflow.
    * The preprocessor guard addresses the "always false" warning
    * from -Wtype-limits on platforms where
@@ -8505,17 +8517,17 @@ build_model(XML_Parser parser) {
   if (dtd->scaffCount > SIZE_MAX / sizeof(XML_Content)) {
     return NULL;
   }
-  if (dtd->contentStringLen > SIZE_MAX / sizeof(XML_Char)) {
+  if (stringCharCount > SIZE_MAX / sizeof(XML_Char)) {
     return NULL;
   }
 #endif
   if (dtd->scaffCount * sizeof(XML_Content)
-      > SIZE_MAX - dtd->contentStringLen * sizeof(XML_Char)) {
+      > SIZE_MAX - stringCharCount * sizeof(XML_Char)) {
     return NULL;
   }

   const size_t allocsize = (dtd->scaffCount * sizeof(XML_Content)
-                            + (dtd->contentStringLen * sizeof(XML_Char)));
+                            + (stringCharCount * sizeof(XML_Char)));

   // NOTE: We are avoiding MALLOC(..) here to so that
   //       applications that are not using XML_FreeContentModel but plain

